package com.smartmart.inventory.service;
import com.smartmart.common.exception.BusinessException; import com.smartmart.inventory.dto.*; import com.smartmart.inventory.entity.Inventory; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.product.repository.ProductRepository; import com.smartmart.receiving.entity.MovementType; import com.smartmart.receiving.entity.StockMovement; import com.smartmart.receiving.repository.StockMovementRepository; import com.smartmart.security.CurrentUserService; import com.smartmart.user.entity.User; import lombok.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class InventoryService { private final InventoryRepository repo; private final ProductRepository products; private final StockMovementRepository movements; private final CurrentUserService currentUser;
 @Transactional public InventoryResponse create(InventoryRequest r){ if(repo.findByProductId(r.getProductId()).isPresent()) throw BusinessException.conflict("Inventory already exists for this product"); return map(repo.save(Inventory.builder().product(products.findById(r.getProductId()).orElseThrow(()->BusinessException.notFound("Product not found"))).quantity(r.getQuantity()).reorderLevel(r.getReorderLevel()).expiryDate(r.getExpiryDate()).discountPercentage(r.getDiscountPercentage()).aisle(r.getAisle()).shelf(r.getShelf()).build())); }
 @Transactional(readOnly=true) public List<InventoryResponse> all(){return repo.findAll().stream().map(this::map).toList();} @Transactional(readOnly=true) public InventoryResponse one(Long id){return map(get(id));} @Transactional(readOnly=true) public InventoryResponse product(Long id){return map(repo.findByProductId(id).orElseThrow(()->BusinessException.notFound("Inventory not found")));}
 @Transactional public InventoryResponse update(Long id, InventoryRequest r){ Inventory i=get(id); i.setProduct(products.findById(r.getProductId()).orElseThrow(()->BusinessException.notFound("Product not found"))); i.setQuantity(r.getQuantity()); i.setReorderLevel(r.getReorderLevel()); i.setExpiryDate(r.getExpiryDate()); i.setDiscountPercentage(r.getDiscountPercentage()); i.setAisle(r.getAisle()); i.setShelf(r.getShelf()); return map(i); }
 @Transactional public void delete(Long id){repo.delete(get(id));} @Transactional(readOnly=true) public List<InventoryResponse> low(){return repo.findLowStock().stream().map(this::map).toList();} @Transactional(readOnly=true) public List<InventoryResponse> expiring(){return repo.findByExpiryDateBetween(LocalDate.now(),LocalDate.now().plusDays(30)).stream().map(this::map).toList();} @Transactional(readOnly=true) public List<InventoryResponse> discounted(){return repo.findByDiscountPercentageGreaterThan(java.math.BigDecimal.ZERO).stream().map(this::map).toList();}
 public Inventory get(Long id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Inventory not found"));} @Transactional public InventoryResponse restock(Long id, RestockRequest r){ if(r.getQuantity()<1) throw BusinessException.badRequest("Restock quantity must be at least 1"); Inventory i=get(id); i.setQuantity(i.getQuantity()+r.getQuantity()); repo.save(i); recordMovement(i, r.getQuantity(), "MANUAL_RESTOCK"); return map(i); } @Transactional public InventoryResponse adjustStock(Long id, AdjustStockRequest r){ if(r.getQuantity()==null) throw BusinessException.badRequest("Adjustment quantity cannot be null"); Inventory i=get(id); int newQty=i.getQuantity()+r.getQuantity(); if(newQty<0) throw BusinessException.badRequest("Cannot adjust stock to negative. Current: "+i.getQuantity()+", requested change: "+r.getQuantity()); i.setQuantity(newQty); repo.save(i); recordMovement(i, r.getQuantity(), r.getReason()); return map(i); }
 /** Audit every bag-less stock change so movement history explains inventory changes. Batch-level rows are reserved for receiving. */
 private void recordMovement(Inventory i, int delta, String reason){ User actor = currentUser.currentUser(); movements.save(StockMovement.builder().product(i.getProduct()).batch(null).type(MovementType.ADJUSTMENT).quantityDelta(delta).referenceType("MANUAL_INVENTORY").referenceId(i.getId()).actorUserId(actor!=null?actor.getId():null).actorName(actor!=null?actor.getName():null).reason(reason).build()); } public InventoryResponse map(Inventory i){return InventoryResponse.builder().id(i.getId()).productId(i.getProduct().getId()).productName(i.getProduct().getName()).quantity(i.getQuantity()).reorderLevel(i.getReorderLevel()).expiryDate(i.getExpiryDate()).discountPercentage(i.getDiscountPercentage()).aisle(i.getAisle()).shelf(i.getShelf()).build();}
}
